Future<List<Message>> _drainMail() async {
  if (_mail.isEmpty) return const [];
  final drained = [
    for (final m in _mail) UserMessage.text('[from ${m.from}] ${m.text}'),
  ];
  _mail.clear();
  // The pending indicator clears at the boundary that delivers (AC3).
  _emitStatus();
  return drained;
}

