/**
 * Waits out panel.js's app-hosting decision (issue #152): the HEAD probe
 * fires AFTER goto() resolved, and with an app bundle it navigates via
 * location.replace — any evaluate in flight then dies with "Execution
 * context was destroyed, most likely because of a navigation". Waiting for
 * the final URL once here settles the page for every later eval. Without
 * the bundle the probe keeps panel.html; nothing to wait for.
 */
export async function awaitPanelSettled(page: Page): Promise<void> {
  if (!appBundlePresent) return;
  await page.waitForURL('**/panel/app/index.html', { timeout: 30_000 });
}

/** Tiny loopback static server for test/browser_ext/fixture/. */
export class FixtureServer {
  private server: http.Server | null = null;
  private boundPort = 0;

  get url(): string {
    return `http://127.0.0.1:${this.boundPort}/`;
  }

  start(): Promise<void> {
    const { promise, resolve } = Promise.withResolvers<void>();
    this.server = http.createServer((req, res) => {
      const rel = (req.url ?? '/').split('?')[0];
      // Contain to fixtureRoot (CodeQL js/path-injection): resolve kills
      // ".." segments, then the prefix check refuses anything that escaped
      // the root — this loopback server is test-only, but the check is
      // cheap and keeps the security gate green without a dismissal.
      const file = path.resolve(
        fixtureRoot,
        rel === '/' ? 'index.html' : `.${rel}`,
      );
      if (!file.startsWith(fixtureRoot + path.sep)) {
        res.statusCode = 403;
        res.end();
        return;
      }
      fs.readFile(file, (err, data) => {
        if (err) {
          res.statusCode = 404;
          res.end();
          return;
        }
        res.setHeader(
          'content-type',
          file.endsWith('.js')
            ? 'text/javascript; charset=utf-8'
            : 'text/html; charset=utf-8',
        );
        res.end(data);
      });
    });
    this.server.listen(0, '127.0.0.1', () => {
      this.boundPort = (this.server!.address() as { port: number }).port;
      resolve();
    });
    return promise;
  }

  stop(): Promise<void> {
    const { promise, resolve } = Promise.withResolvers<void>();
    this.server?.close(() => resolve());
    this.server = null;
    return promise;
  }
}

