    const b = await portMsg(page, 'attached');
    const sessionB = b?.['sessionId'] as string;
    expect(sessionB).toBeTruthy();
    expect(sessionB).not.toBe(sessionA);
    await portSend(page, {
      kind: 'prompt',
      id: 'j-b',
      text: 'какие вкладки ты видишь',
