        if (m['kind'] !== 'message_done') return false;
        // Live rows nest the payload under `message`.
        const msg = (m['message'] ?? m) as Msg;
        return (
          msg['role'] === 'assistant' &&
          String(msg['text'] ?? '').startsWith('fake:')
        );
      });
      return found ?? null;
    }, { timeout: 45_000 })
    .not.toBeNull();
  return found!;
}

