/** Types one prompt into the panel composer and sends it via `how`. */
async function ask(
  fa: { panel: Page },
  text: string,
  how: 'enter' | 'click',
): Promise<void> {
  await fa.panel.fill('#prompt', text);
  if (how === 'enter') {
    await fa.panel.press('#prompt', 'Enter');
  } else {
    await fa.panel.click('#sendPrompt');
  }
}

